\begin{lemma} \label{lem:helper0}
	Suppose $M(x,y)$ is $\mu$-strongly convex-strongly concave on a convex set $S=S_x\times S_y$, then it holds for any $(x,y),(x',y') \in S$ that
	$$\mu\left\|\begin{bmatrix} x-x' \\ y-y' \end{bmatrix}\right\|^2 \leq \left(\begin{bmatrix} \nabla_x M(x,y)  \\-\nabla_y M(x,y) \end{bmatrix} -\begin{bmatrix} \nabla_x M(x',y')  \\-\nabla_y M(x',y') \end{bmatrix}\right)^T\begin{bmatrix} x-x' \\ y-y' \end{bmatrix}.$$
	When $\nabla M(x', y')=0$, the distance to this stationary point is bounded by
	$$
	\left\|\begin{bmatrix} x-x' \\ y-y' \end{bmatrix}\right\| \leq \frac{\|\nabla M(x,y)\|}{\mu} \ . 
	$$
\end{lemma}

\begin{theorem} \label{thm:standard-contraction}
	Consider any minimax problem $\min_{x\in\RR^n}\max_{y\in\RR^m} M(x,y)$ where $M(x,y)$ is $\beta$-smooth and $\mu$-strongly convex-strongly concave on a set $B(x_0,r)\times B(y_0,r)$ with $r\geq 2\|\nabla M(x_0,y_0)\|/\mu$. Then GDA~\eqref{eq:GDA} with step-size $s\in(0, 2\mu/\beta^2) $ linearly converges to a stationary point $(x^*,y^*)\in B((x_0,y_0),r/2)$ with
	$$ \left\|\begin{bmatrix} x_k-x^* \\ y_k-y^* \end{bmatrix}\right\|^2 \leq \left(1 - 2\mu s+\beta^2s^2\right)^{k}\left\|\begin{bmatrix} x_0-x^* \\ y_0-y^* \end{bmatrix}\right\|^2.$$
\end{theorem}

\begin{lemma} \label{lem:grad-formula}
	The gradient of the saddle envelope $L_\eta(x,y)$ at $z=(x,y)$ is
	$$ \begin{bmatrix} \nabla_x L_\eta(z)\\  \nabla_y L_\eta(z)\end{bmatrix} = \begin{bmatrix} \eta(x-x_+)\\ \eta(y_+-y) \end{bmatrix} = \begin{bmatrix} \nabla_x L(z_+)\\  \nabla_y L(z_+)\end{bmatrix}$$
	where $z_+ = (x_+,y_+) = \prox_\eta(z)$ is given by the proximal operator.
\end{lemma}

\begin{proof}
	Notice that the saddle envelope is a composition of Moreau envelopes
	\begin{align*}
	L_{\eta}(x,y) &= \min_{u} \left(\max_{v} L(u,v) - \frac{\eta}{2}\|v-y\|^2\right) + \frac{\eta}{2}\|u-x\|^2\\
	&= \min_{u}\ -e_\eta\{-L(u,\cdot)\}(y) + \frac{\eta}{2}\|u-x\|^2 = e_{\eta}\{g(\cdot,y)\}(x)
	\end{align*}
	where $g(u,y) = -e_{\eta}\{-L(u,\cdot)\}(y)$. Applying the gradient formula~\eqref{eq:moreau-grad} gives our first claimed gradient formula in $x$ of
	$\nabla_x L_\eta(x,y) = \eta (x-x_+)$
	since $x_+$ is the unique minimizer of $u \mapsto g(u,y) + \frac{\eta}{2}\|u-x\|^2$. Symmetric reasoning gives our first claimed formula $\nabla_y L_\eta(x,y) = \eta (y_+-y) $ in $y$.
	The second claimed equality is precisely the first-order optimality condition for~\eqref{eq:prox-definition}. 
\end{proof}

\begin{corollary} \label{cor:stationarity}
	The stationary points of $L_\eta$ are exactly the same as those of $L$.
\end{corollary}

\begin{proof}
	First consider any stationary point $z=(x,y)$ of $L$. Denote $z_+=\prox_\eta(z)$ and the objective function defining the proximal operator~\eqref{eq:prox-definition} as $M(u,v) = L(u,v) + \frac{\eta}{2}\|u-x\|^2-\frac{\eta}{2}\|v-y\|^2$. Then observing that $\nabla M(z)=0$, $z$ must be the unique minimax point of $M$ (that is, $z=z_+=\prox_\eta(z)$). Hence $z$ must be a stationary point of $L_\eta$ as well since $\nabla L_\eta(z) =\nabla L(z_+)=\nabla L(z)= 0$.

	Conversely consider a stationary point $z=(x,y)$ of $L_\eta$. Then $\eta(x-x_+) = \nabla_x L_\eta(z)=0$ and $\eta(y_+-y) = \nabla_y L_\eta(z)=0$. Hence we again find that $z=z_+=\prox_\eta(z)$ and consequently, this point must be a stationary point of $L$ as well since $\nabla L(z)=\nabla L(z_+)=\nabla L_\eta(z)=0$.
\end{proof}

\begin{corollary} \label{cor:PPM-to-GDA}
	One step of the (damped) PPM~\eqref{eq:saddle-PPM} on the original objective $L$ is equivalent to one step of GDA~\eqref{eq:GDA} on the saddle envelope $L_\eta$ with $s = \lambda/\eta$. 
\end{corollary}

\begin{proof}
	Let $(x^+_k,y^+_k) = \prox_\eta(x_k,y_k)$ and let $(x_{k+1}, y_{k+1})$ be a step of GDA on $L_\eta(x,y)$ from $(x_k,y_k)$ with step-size $s=\lambda/\eta$. Then
	\begin{align*}
	\begin{bmatrix} x_{k+1} \\ y_{k+1} \end{bmatrix} = \begin{bmatrix} x_{k} \\ y_{k}\end{bmatrix} - s\begin{bmatrix} \nabla_xL_\eta(z_k) \\ -\nabla_yL_\eta(z_k)\end{bmatrix}
	&= \begin{bmatrix} x_{k} \\ y_{k}\end{bmatrix} - \frac{\lambda}{\eta}\begin{bmatrix} \eta(x_k-x^+_k) \\ -\eta(y^+_k-y_k) \end{bmatrix}
	= (1-\lambda)\begin{bmatrix} x_{k} \\ y_{k}\end{bmatrix} + \lambda\begin{bmatrix} x^+_k \\ y^{+}_k \end{bmatrix}
	\end{align*}
	follows from Lemma~\ref{lem:grad-formula}.
\end{proof}

\begin{lemma} \label{lem:hess-formula}
	The Hessian of the saddle envelope $L_\eta(z)$ is
	$$ \begin{bmatrix} \nabla^2_{xx} L_\eta(z) & \nabla^2_{xy} L_\eta(z)\\  -\nabla^2_{yx}L_\eta(z) & -\nabla^2_{yy} L_\eta(z)\end{bmatrix} = \eta I-\eta^2\left(\eta I+ \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\right)^{-1} $$
	where $z_+ = \prox_\eta(z)$. Since $\eta>\rho$, we have
	$$ \nabla^2_{xx} L_\eta(z) = \eta I -\eta^2\left(\eta I +\nabla_{xx} L(z_+) + \nabla^2_{xy} L(z_+)(\eta I -\nabla^2_{yy} L(z_+))^{-1}\nabla^2_{yx} L(z_+)\right)^{-1},$$
	$$ \nabla^2_{yy} L_\eta(z) = -\eta I +\eta^2\left(\eta I +\nabla_{yy} L(z_+) + \nabla^2_{yx} L(z_+)(\eta I +\nabla^2_{xx} L(z_+))^{-1}\nabla^2_{xy} L(z_+)\right)^{-1}.$$
\end{lemma}

\begin{proof}
	Consider some $z=(x,y)$ and a nearby point $z^\Delta=z+\Delta$. Denote one proximal step from each of these points by $z_+=(x_+,y_+)= \prox_\eta(z)$ and $z^\Delta_+=(x^\Delta_+,y^\Delta_+)= \prox_\eta(z^\Delta)$. 
	Then our claimed Hessian formula amounts to showing
	\begin{align*}
		\begin{bmatrix} \nabla_x L_\eta(z^\Delta) \\ -\nabla_y L_\eta(z^\Delta) \end{bmatrix} - \begin{bmatrix} \nabla_x L_\eta(z) \\ -\nabla_y L_\eta(z) \end{bmatrix}  &= \left(\eta I - \eta^2\left(\eta I + \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\right)^{-1}\right)\begin{bmatrix} \Delta_x\\ \Delta_y  \end{bmatrix} +o(\|\Delta\|).
	\end{align*}
	Recall Lemma~\ref{lem:grad-formula} showed the gradient of the saddle envelope is given by $\nabla_x L_\eta(z) = \eta(x-x_+)$ and $\nabla_y L_\eta(z) = \eta(y_+-y)$. Applying this at $z$ and $z_+$ and dividing by $\eta$, our claimed Hessian formula becomes
	\begin{equation} \label{eq:target-hessian-condition}
	\begin{bmatrix} x^\Delta_+-x_+\\ y^\Delta_+-y_+ \end{bmatrix} = \eta\left(\eta I + \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\right)^{-1}\begin{bmatrix} \Delta_x\\ \Delta_y \end{bmatrix} +o(\|\Delta\|) \ .
	\end{equation}
	Our proof shows this in two steps: first considering a proximal step on the second-order Taylor approximation of $L$ at $z_+$ and then showing this closely matches the result of a proximal step on $L$.

	First, consider the following quadratic model of the objective around $z_+$:
	$$ \widetilde L(z) = L(z_+) + \nabla L(z_+)^T(z-z_+) + \frac{1}{2}(z-z_+)^T\nabla^2 L(z_+)(z-z_+) \ . $$
	Denote the result of one proximal step on $\widetilde L$ from $z^\Delta$ by $\widetilde z^\Delta_+ = (\widetilde x_+^\Delta, \widetilde y_+^\Delta)$. Since the proximal subproblem is strongly convex-strongly concave, this solution is uniquely determined by
	$$
	\begin{bmatrix} \nabla_x \widetilde L(\widetilde x^\Delta_+,\widetilde y^\Delta_+)\\  -\nabla_y \widetilde L(\widetilde x^\Delta_+,\widetilde y^\Delta_+)\end{bmatrix} + \begin{bmatrix} \eta(\widetilde x^\Delta_+-x^\Delta)\\ \eta(\widetilde y^\Delta_+-y^\Delta) \end{bmatrix} = 0 \ .
	$$
	Plugging in the definition of our quadratic model $\widetilde L$ yields
	\begin{align*}
	&\begin{bmatrix} \nabla_x L(z_+)\\ -\nabla_y L(z_+)\end{bmatrix} + \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\begin{bmatrix} \widetilde x^\Delta_+-x_+\\ \widetilde y^\Delta_+-y_+ \end{bmatrix} + \begin{bmatrix} \eta(\widetilde x^\Delta_+-x^\Delta)\\ \eta(\widetilde y^\Delta_+-y^\Delta) \end{bmatrix} = 0 \ .
	\end{align*}
	Hence
	\begin{align*}
	& \left(\eta I + \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\right)\begin{bmatrix} \widetilde x^\Delta_+-x_+\\  \widetilde y^\Delta_+-y_+ \end{bmatrix} = \eta \begin{bmatrix} x^\Delta - x_+ -\eta^{-1}\nabla_x L(z_+) \\ y^\Delta - y_+ +\eta^{-1}\nabla_y L(z_+) \end{bmatrix}\\
	&\implies  \left(\eta I + \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\right)\begin{bmatrix} \widetilde x^\Delta_+-x_+\\  \widetilde y^\Delta_+-y_+ \end{bmatrix} = \eta \begin{bmatrix} \Delta_x\\ \Delta_y \end{bmatrix}\\
	&\implies  \begin{bmatrix} \widetilde x^\Delta_+-x_+\\ \widetilde y^\Delta_+-y_+ \end{bmatrix} = \eta\left(\eta I + \begin{bmatrix} \nabla^2_{xx} L(z_+) & \nabla^2_{xy} L(z_+)\\  -\nabla^2_{yx} L(z_+) & -\nabla^2_{yy} L(z_+)\end{bmatrix}\right)^{-1}\begin{bmatrix} \Delta_x\\ \Delta_y \end{bmatrix}.
	\end{align*}

	This is nearly our target condition~\eqref{eq:target-hessian-condition}. All that remains is to show our second-order approximation satisfies $\| z^\Delta_+ - \widetilde z^\Delta_+\| = o(\|\Delta\|)$.
	Denote the proximal subproblem objective by $ M^\Delta (u,v) = L(u,v) + \frac{\eta}{2}\|u-x^\Delta\|^2 - \frac{\eta}{2}\|v-y^\Delta\|^2$ and its approximation by $\widetilde M^\Delta (u,v) = \widetilde L(u,v) + \frac{\eta}{2}\|u-x^\Delta\|^2 - \frac{\eta}{2}\|v-y^\Delta\|^2$.
	Noting that $\|\nabla \widetilde M^\Delta (x_+,y_+)\| = \eta\|\Delta\|$, we can apply Lemma~\ref{lem:helper0} to the $(\eta-\rho)$-strongly convex-strongly concave function $\widetilde M^\Delta$ to bound the distance to its minimax point as
	$$ \|z_+-\widetilde z_+^\Delta\|\leq \frac{\eta}{\eta-\rho}\|\Delta\| \ .$$
	Consequently, we can bound difference in gradients between $L$ and its quadratic model $\widetilde L$ at $\widetilde z^\Delta_+$ by $ \|\nabla L(\widetilde z^\Delta_+) - \nabla \widetilde L(\widetilde z^\Delta_+)\| = o(\|\Delta\|)$. Therefore $\|\nabla M^\Delta(\widetilde z^\Delta_+)\| = o(\|\Delta\|)$ and so applying Lemma~\ref{lem:helper0} to the strongly convex-strongly concave function $M^\Delta$ bounds the distance to its minimax point as $\|z^\Delta_+ - \widetilde z^\Delta_+\| = o(\|\Delta\|)$, which completes our proof.
\end{proof}

\begin{proposition} \label{prop:hessians}
	If the $x$-interaction dominance~\eqref{eq:x-dominance} holds with $\alpha\in\RR$, the saddle envelope is smooth and weakly convex with respect to $x$ 
	$$  (\eta^{-1} + \alpha^{-1})^{-1}I \preceq \nabla^2_{xx}L_\eta(z) \preceq \eta I\ ,$$
	and if the $y$-interaction dominance condition~\eqref{eq:y-dominance} holds with $\alpha\in\RR$, the saddle envelope is smooth and weakly concave with respect to $y$
	$$  (\eta^{-1} + \alpha^{-1})^{-1}I \preceq -\nabla^2_{yy}L_\eta(z) \preceq \eta I\ .$$
\end{proposition}

\begin{proof}
	Recall the formula for the $x$ component of the Hessian given by Lemma~\ref{lem:hess-formula}.
	Then the interaction dominance condition~\eqref{eq:x-dominance} can lower bound this Hessian by
	\begin{align*}
	\nabla^2_{xx} L_\eta(z) &=\eta I -\eta^2\left(\eta I +\nabla_{xx} L(z_+) + \nabla^2_{xy} L(z_+)(\eta I -\nabla^2_{yy} L(z_+))^{-1}\nabla^2_{yx} L(z_+)\right)^{-1}\\
	&\succeq \eta I -\eta^2\left(\eta I +\alpha I\right)^{-1}\\
	&=(\eta - \eta^2/(\eta+\alpha))I\\
	&=(\eta^{-1} + \alpha^{-1})^{-1}I \ .
	\end{align*}
	Note that $\eta I +\nabla^2_{xx} L(z_+)$ is positive definite (since $\eta>\rho$) and $\nabla^2_{xy} L(z_+)(\eta I +\nabla^2_{yy} L(z_+))^{-1}\nabla^2_{yx} L(z_+)$ is positive semidefinite (since its written as a square). Then the inverse of their sum must also be positive definite and consequently $\nabla^2_{xx} L_\eta(z)$ is upper bounded by
	\begin{align*}
	\eta I -\eta^2\left(\eta I +\nabla_{xx} L(z_+) + \nabla^2_{xy} L(z_+)(\eta I +\nabla^2_{yy} L(z_+))^{-1}\nabla^2_{yx} L(z_+)\right)^{-1} &\preceq \eta I \ .
	\end{align*}
	Symmetric reasoning applies to give bounds on $\nabla^2_{yy} L_\eta(z)$.
\end{proof}

\begin{proposition}\label{prop:smoothness}
	$L_\eta$ has $\max\{\eta, |\eta^{-1}-\rho^{-1}|^{-1}\}$-Lipschitz gradient.
\end{proposition}

\begin{proof}
	Consider two points $z=(x,y)$ and $\bar z = (\bar x, \bar y)$ and denote one proximal step from each of them by $z_+=(x_+,y_+) = \prox_\eta(z)$ and $\bar z_+ = (\bar x_+,\bar y_+) = \prox_\eta(\bar z)$.
	Define the  $(\eta-\rho)$-strongly convex-strongly concave function underlying the computation of the saddle envelope at $z$ as
	$$ M(u,v) = L(u,v) + \frac{\eta}{2}\|u-x\|^2 -\frac{\eta}{2}\|v-y\|^2. $$
	First we compute the gradient of $M$ at $\bar z_+$ which is given by
	\begin{align*}
	\begin{bmatrix} \nabla_x M(\bar z_+) \\ \nabla_y M(\bar z_+)\end{bmatrix} =  \begin{bmatrix} \nabla_x L(\bar z_+) + \eta(\bar x_+-x) \\ \nabla_y L(\bar z_+) - \eta(\bar y_+-y)\end{bmatrix}
	%=  \begin{bmatrix} \nabla_x L(\bar z_+) + \eta(\bar x_+-\bar x+\bar x-x) \\ \nabla_y L(\bar z_+) - \eta(\bar y_+-\bar y+\bar y-y)\end{bmatrix}\
	= \eta \begin{bmatrix} \bar x-x \\ y-\bar y\end{bmatrix}.
	\end{align*}
	Applying Lemma~\ref{lem:helper0}, and noting that $z_+=\prox_\eta(z)$ has $\nabla M(z_+)=0$ yields
	$$ \left\|\begin{bmatrix} \bar x_+-x_+ \\ \bar y_+-y_+ \end{bmatrix}\right\|^2 \leq \frac{\eta}{\eta-\rho} \begin{bmatrix} \bar x- x \\ \bar y- y \end{bmatrix}^T\begin{bmatrix} \bar x_+-x_+ \\ \bar y_+-y_+ \end{bmatrix}.$$
	Recalling the saddle envelope's gradient formula from Lemma~\ref{lem:grad-formula}, we can upper bound the difference between its gradients at $z$ and $\bar z$ by
	\begin{align*}
	\frac{1}{\eta^{2}}\|\nabla L_\eta(z) - \nabla L_\eta(\bar z)\|^2
	&= \left\|\begin{bmatrix} x-x_+ \\ y_+-y \end{bmatrix} - \begin{bmatrix} \bar x-\bar x_+ \\ \bar y_+-\bar y \end{bmatrix}\right\|^2\\
	&=\left\|\begin{bmatrix} x-\bar x \\ y-\bar y \end{bmatrix}\right\|^2 + 2 \begin{bmatrix} x-\bar x \\ y-\bar y \end{bmatrix}^T\begin{bmatrix} \bar x_+- x_+ \\ \bar y_+- y_+ \end{bmatrix} +\left\|\begin{bmatrix} \bar x_+- x_+ \\ \bar y_+- y_+ \end{bmatrix}\right\|^2\\
	&\leq \left\|\begin{bmatrix} x-\bar x \\ y-\bar y \end{bmatrix}\right\|^2 + \left(\frac{\eta}{\eta-\rho}-2\right)\begin{bmatrix} \bar x- x \\ \bar y- y \end{bmatrix}^T\begin{bmatrix} \bar x_+- x_+ \\ \bar y_+- y_+ \end{bmatrix}.
	\end{align*}
	Notice that $\begin{bmatrix} \bar x- x \\ \bar y- y \end{bmatrix}^T\begin{bmatrix} \bar x_+- x_+ \\ \bar y_+- y_+ \end{bmatrix}$ is non-negative but the sign of $\left(\frac{\eta}{\eta-\rho}-2\right)$ may be positive or negative. If this coefficient is negative, we can upperbound the second term above by zero, giving $	\|\nabla L_\eta(z) - \nabla L_\eta(\bar z)\|^2 \leq \eta^2\left\|z-\bar z\right\|^2 .$
