	\begin{align*}
	\|\nabla L_\eta(z) - \nabla L_\eta(\bar z)\|^2 &\leq \eta^2\left(1 + \left(\frac{\eta}{\eta-\rho}-2\right)\frac{\eta}{\eta-\rho}\right)\left\|\begin{bmatrix} x-\bar x \\ y-\bar y \end{bmatrix}\right\|^2 \\
	&= \eta^2\left(\frac{\eta}{\eta-\rho}-1\right)^2\left\|\begin{bmatrix} x-\bar x \\ y-\bar y \end{bmatrix}\right\|^2 \\
	&= \left(\frac{\eta\rho}{\eta-\rho}\right)^2\left\|\begin{bmatrix} x-\bar x \\ y-\bar y \end{bmatrix}\right\|^2 \ .
	\end{align*}
	by Cauchy–Schwarz and using that $\left\|\begin{bmatrix} \bar x_+- x_+ \\ \bar y_+- y_+ \end{bmatrix}\right\| \leq \frac{\eta}{\eta-\rho}\left\|\begin{bmatrix} \bar x- x \\ \bar y- y \end{bmatrix}\right\|$.
\end{proof}

\subsection{Proof of Theorem~\ref{thm:two-sided-dominance}}
Propositions~\ref{prop:hessians} and~\ref{prop:smoothness} show that $L_\eta$ is $\mu=(\eta^{-1}+\alpha^{-1})^{-1}$-strongly convex-strongly concave and has a $\beta=\max\{\eta, |\eta^{-1}-\rho^{-1}|^{-1}\}$-Lipschitz gradient. Having strong convexity and strong concavity ensures $L_\eta$ has a unique stationary point $(x^*,y^*)$, which in turn must be the unique stationary point of $L$ by Corollary~\ref{cor:stationarity}. 
Recall Corollary~\ref{cor:PPM-to-GDA} showed that the damped PPM~\eqref{eq:saddle-PPM} on $L$ is equivalent to GDA~\eqref{eq:GDA} with $s=\lambda/\eta$ on $L_\eta$. Then provided 
$$ \lambda \leq 2\frac{\min\left\{1,(\eta/\rho-1)^2\right\}}{\eta/\alpha+1} = \frac{2(\eta^{-1}+\alpha^{-1})^{-1}}{\max\{\eta^2, (\eta^{-1}-\rho^{-1})^{-2}\}}\ , $$
we have $s=\lambda/\eta\in(0,2\mu/\beta^2)$. Hence applying Theorem~\ref{thm:standard-contraction} shows the iterations of GDA (and consequently PPM) linearly converge to this unique stationary point as
\begin{align*}
\left\|\begin{bmatrix} x_k-x^* \\ y_k-y^* \end{bmatrix}\right\|^2 &\leq \left(1 - \frac{2\lambda}{\eta/\alpha+1} + \frac{\lambda^2}{\min\left\{1,(\eta/\rho-1)^2\right\}}\right)^{k}\left\|\begin{bmatrix} x_0-x^* \\ y_0-y^* \end{bmatrix}\right\|^2.
\end{align*}




\subsection{Proof of Lemma~\ref{lem:helper0}}
Observe that the assumed strong convexity and strong concavity ensures
\begin{align*}
M(x',y') \leq &M(x,y') -\nabla_x M(x',y')^T(x-x')- \frac{\mu}{2}\|x-x'\|^2\\
&\leq M(x,y) + \nabla_y M(x,y)^T(y'-y) -\nabla_x M(x',y')^T(x-x') - \frac{\mu}{2}\|y-y'\|^2 - \frac{\mu}{2}\|x-x'\|^2
\end{align*}
and symmetrically,
\begin{align*}
M(x',y') &\geq M(x',y) - \nabla_y M(x',y')^T(y-y') + \frac{\mu}{2}\|y-y^*\|^2\\
&\geq M(x,y) + \nabla_x M(x,y)^T(x'-x) - \nabla_y M(x',y')^T(y-y') + \frac{\mu}{2}\|x-x'\|^2 + \frac{\mu}{2}\|y-y'\|^2.
\end{align*}
Combining the above two inequalities gives the first claimed inequality
\begin{equation*}
\mu\left\|\begin{bmatrix} x-x' \\ y-y' \end{bmatrix}\right\|^2 \leq \left(\begin{bmatrix} \nabla_x M(x,y)  \\-\nabla_y M(x,y) \end{bmatrix} -\begin{bmatrix} \nabla_x M(x',y')  \\-\nabla_y M(x',y') \end{bmatrix}\right)^T\begin{bmatrix} x-x' \\ y-y' \end{bmatrix}.
\end{equation*}
Furthermore, when $\nabla M(x',y')=0$, Cauchy–Schwarz gives the second inequality.

