\begin{lemma} \label{lem:helper1}
	Suppose $M$ is $\mu$-strongly convex-strongly concave in a set $B(x,r)\times B(y,r)$ for some fixed $(x,y)$ and $r\geq 2\|\nabla M(x,y)\|/\mu$, then there exists a stationary point of $M$ in $B((x,y),r/2)$.
\end{lemma}

\begin{proof}
	Consider the following constrained minimax problem $ \min_{x'\in B(x,r)} \max_{y'\in B(y,r)} M(x,y).$
	Since $M(x,y)$ is strongly convex-strongly concave, it must have a unique solution $(x^*,y^*)$.
	The first-order optimality condition for $(x^*,y^*)$ ensures
	$$ \nabla_x M(x^*,y^*) =-\lambda(x^*-x) \ \ \ \text{ and } \ \ \  -\nabla_y M(x^*,y^*) =-\gamma(y^*-y)$$
	for some constants $\lambda,\gamma\geq 0$ that are nonzero only if $x^*$ or $y^*$ are on the boundary of $B(x,r)$ and $B(y,r)$ respectively. Taking an inner product with $(x^*-x,y^*-y)$ gives
	\begin{equation}\label{eq:lemA2.1}
	\begin{bmatrix} \nabla_x M(x^*,y^*)  \\-\nabla_y M(x^*,y^*) \end{bmatrix}^T\begin{bmatrix} x^*-x  \\ y^*-y \end{bmatrix} =-\left\|\begin{bmatrix}\sqrt{\lambda}(x^*-x)  \\ \sqrt{\gamma}(y^*-y) \end{bmatrix}\right\|^2\leq0.
	\end{equation}
	Applying Lemma~\ref{lem:helper0} and utilizing \eqref{eq:lemA2.1}, we conclude that
	\begin{equation}\label{eq:lemA2.2}
	\mu\left\|\begin{bmatrix} x^*-x  \\ y^*-y \end{bmatrix}\right\|^2 + \begin{bmatrix} \nabla_x M(x,y)  \\-\nabla_y M(x,y) \end{bmatrix}^T\begin{bmatrix} x^*-x  \\ y^*-y \end{bmatrix}\leq 0. 
	\end{equation}
	Hence
	$$ \left\|\begin{bmatrix} x^*-x  \\ y^*-y \end{bmatrix}\right\|^2 \leq \frac{1}{\mu}\left\|\begin{bmatrix} \nabla_x M(x,y)  \\-\nabla_y M(x,y) \end{bmatrix}\right\|\left\|\begin{bmatrix} x^*-x  \\ y^*-y \end{bmatrix}\right\|\ ,$$
	whereby
	$$ \left\|\begin{bmatrix} x^*-x  \\ y^*-y \end{bmatrix}\right\| \leq \frac{1}{\mu}\left\|\begin{bmatrix} \nabla_x M(x,y)  \\-\nabla_y M(x,y) \end{bmatrix}\right\| \leq r/2\ ,$$
	utilizing our assumed condition on $r$.
	Since $(x^*,y^*)$ lies strictly inside $B((x,y),r)$, the first-order optimality condition implies $(x^*,y^*)$ is a stationary point of $M$.
\end{proof}

Lemma~\ref{lem:helper1} ensures the existence of a nearby stationary point $(x^*,y^*)$. Then the standard proof for strongly monotone (from Lemma~\ref{lem:helper0}) and Lipschitz operators gives a contraction whenever $s\in(0, 2\mu/\beta^2) $:
\begin{align*}
\left\|\begin{bmatrix} x_{k+1}-x^* \\ y_{k+1}-y^* \end{bmatrix}\right\|^2
&= \left\|\begin{bmatrix} x_{k}-x^* \\ y_{k}-y^* \end{bmatrix}\right\|^2 - 2s\begin{bmatrix} \nabla_x M(x_k,y_k) \\ -\nabla_y M(x_k,y_k) \end{bmatrix}^T\begin{bmatrix} x_k-x^* \\ y_k-y^* \end{bmatrix} + s^2\left\|\begin{bmatrix} \nabla_x M(x_k,y_k) \\ -\nabla_y M(x_k,y_k) \end{bmatrix}\right\|^2\\
