\begin{theorem} \label{thm:standard-contraction}
	Consider any minimax problem $\min_{x\in\RR^n}\max_{y\in\RR^m} M(x,y)$ where $M(x,y)$ is $\beta$-smooth and $\mu$-strongly convex-strongly concave on a set $B(x_0,r)\times B(y_0,r)$ with $r\geq 2\|\nabla M(x_0,y_0)\|/\mu$. Then GDA~\eqref{eq:GDA} with step-size $s\in(0, 2\mu/\beta^2) $ linearly converges to a stationary point $(x^*,y^*)\in B((x_0,y_0),r/2)$ with
	$$ \left\|\begin{bmatrix} x_k-x^* \\ y_k-y^* \end{bmatrix}\right\|^2 \leq \left(1 - 2\mu s+\beta^2s^2\right)^{k}\left\|\begin{bmatrix} x_0-x^* \\ y_0-y^* \end{bmatrix}\right\|^2.$$
\end{theorem}

\begin{lemma} \label{lem:helper1}
