\begin{lemma} \label{lem:grad-formula}
	The gradient of the saddle envelope $L_\eta(x,y)$ at $z=(x,y)$ is
	$$ \begin{bmatrix} \nabla_x L_\eta(z)\\  \nabla_y L_\eta(z)\end{bmatrix} = \begin{bmatrix} \eta(x-x_+)\\ \eta(y_+-y) \end{bmatrix} = \begin{bmatrix} \nabla_x L(z_+)\\  \nabla_y L(z_+)\end{bmatrix}$$
	where $z_+ = (x_+,y_+) = \prox_\eta(z)$ is given by the proximal operator.
\end{lemma}

\begin{proof}
	Notice that the saddle envelope is a composition of Moreau envelopes
	\begin{align*}
	L_{\eta}(x,y) &= \min_{u} \left(\max_{v} L(u,v) - \frac{\eta}{2}\|v-y\|^2\right) + \frac{\eta}{2}\|u-x\|^2\\
	&= \min_{u}\ -e_\eta\{-L(u,\cdot)\}(y) + \frac{\eta}{2}\|u-x\|^2 = e_{\eta}\{g(\cdot,y)\}(x)
	\end{align*}
	where $g(u,y) = -e_{\eta}\{-L(u,\cdot)\}(y)$. Applying the gradient formula~\eqref{eq:moreau-grad} gives our first claimed gradient formula in $x$ of
	$\nabla_x L_\eta(x,y) = \eta (x-x_+)$
	since $x_+$ is the unique minimizer of $u \mapsto g(u,y) + \frac{\eta}{2}\|u-x\|^2$. Symmetric reasoning gives our first claimed formula $\nabla_y L_\eta(x,y) = \eta (y_+-y) $ in $y$.
	The second claimed equality is precisely the first-order optimality condition for~\eqref{eq:prox-definition}. 
\end{proof}

